{
  "pipeline_type": "user_stories",
  "message": "Build a simple todo list app for personal task tracking, with due dates and priority levels."
}

{
  "pipeline_type": "od_ppt",
  "message": "Create a 10-slide investor pitch deck for a B2B SaaS analytics startup, covering problem, solution, market size, product, traction, and ask.",
  "template_id": "guizang-ppt"
}

{
  "target_artifact_type": "ppt",
  "instruction": "Make the traction slide more data-heavy with a growth chart callout."
}

{
  "pipeline_type": "od_prototype",
  "message": "Build a focused landing page for an AI code review tool aimed at engineering managers.",
  "template_id": "saas-landing",
  "design_system_id": "linear-app",
  "discovery": {
    "audience": "engineering managers",
    "cta": "Start free trial"
  }
}

{
  "target_artifact_type": "prototype",
  "instruction": "Add a pricing section with three tiers below the hero."
}

{
  "pipeline_type": "app_builder",
  "message": "Build a small internal expense-tracking app: employees submit expenses with receipts, managers approve or reject them, finance exports approved expenses to CSV."
}

{
  "target_artifact_type": "app_builder",
  "instruction": "Add a monthly spend-by-category report for finance."
}

{
  "pipeline_type": "dotnet_to_azure",
  "message": "Modernize a monolithic .NET Framework 4.8 web app (Web Forms + SQL Server on a VM) that manages customer support tickets, moving it to .NET 8 on Azure App Service with Azure SQL."
}

{
  "target_artifact_type": "dotnet_to_azure",
  "instruction": "Use Azure Key Vault for the connection string instead of appsettings.json."
}

{
  "pipeline_type": "mulesoft_to_springboot",
  "message": "Migrate a MuleSoft integration app that syncs orders between Salesforce and an internal SAP system via a REST API and a scheduled batch job, to Spring Boot on our own infrastructure."
}

{
  "target_artifact_type": "mulesoft_to_springboot",
  "instruction": "Add retry-with-backoff around the SAP call in the scaffolded scheduler."
}

{
  "pipeline_type": "custom",
  "message": "Research the competitive landscape for AI-assisted code review tools and produce a SWOT analysis with a prioritized roadmap.",
  "agent_ids": [
    "market-research-agent",
    "swot-analyst",
    "roadmap-planner"
  ]
}
